#include <stdio.h>

int main() {
    int data[] = {34, -5, 78, 12, 0, 56};
    int n = sizeof(data) / sizeof(data[0]);
    int max = data[0], min = data[0];
    for (int i = 1; i < n; i++) {
        if (data[i] > max) max = data[i];
        if (data[i] < min) min = data[i];
    }
    printf("Max: %d\nMin: %d\n", max, min);
    return 0;
}
